package org.marketreview.nativeapp;
import org.json.*;import java.util.*;
public final class AccountEditModel {
 private AccountEditModel(){}static void need(boolean v,String m){if(!v)throw new IllegalArgumentException(m);}
 static void valid(JSONObject a){need(a.opt("id") instanceof String&&!a.optString("id").isEmpty()&&a.optString("id").length()<=100,"账户完整ID无效");need(Arrays.asList("ledger","paper").contains(a.optString("type")),"账户类型无效");}
 static boolean equal(Object a,Object b)throws Exception{if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;if(x.length()!=y.length())return false;Iterator<String> keys=x.keys();while(keys.hasNext()){String k=keys.next();if(!y.has(k)||!equal(x.get(k),y.get(k)))return false;}return true;}if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;if(x.length()!=y.length())return false;for(int n=0;n<x.length();n++)if(!equal(x.get(n),y.get(n)))return false;return true;}if(a instanceof Number&&b instanceof Number)return ((Number)a).doubleValue()==((Number)b).doubleValue();return Objects.equals(a,b);}
 public static void check(JSONObject expected,JSONObject current)throws Exception{valid(expected);valid(current);need(equal(expected,current),"账户已变化；草稿保留，请重读后编辑");}
 public static JSONObject draft(JSONObject a)throws Exception{valid(a);JSONObject d=new JSONObject();for(String k:new String[]{"name","broker","maskedNumber","note"})d.put(k,a.opt(k) instanceof String?a.opt(k):"");return d.put("editCash",false).put("cashText",a.opt("cashBalance") instanceof Number?a.opt("cashBalance").toString():"");}
 public static JSONObject propose(JSONObject expected,JSONObject d)throws Exception{valid(expected);need(d.length()==6&&d.opt("editCash") instanceof Boolean,"草稿字段无效");JSONObject candidate=new JSONObject(expected.toString());for(String k:new String[]{"name","broker","maskedNumber","note"}){need(d.opt(k) instanceof String,"编辑内容须为文本");Object old=expected.opt(k) instanceof String?expected.opt(k):"";if(!d.get(k).equals(old))candidate.put(k,d.getString(k).strip());}need(!candidate.optString("name").strip().isEmpty(),"账户名称不能为空");need(d.opt("cashText") instanceof String,"现金输入须为文本");boolean fallback=false;if(d.getBoolean("editCash")){String s=d.getString("cashText").strip();double n=0;try{if(!s.isEmpty()){if(s.matches("0[xX][0-9a-fA-F]+|0[bB][01]+|0[oO][0-7]+")){int base=Character.toLowerCase(s.charAt(1))=='x'?16:Character.toLowerCase(s.charAt(1))=='b'?2:8;for(int i=2;i<s.length();i++)n=n*base+Character.digit(s.charAt(i),base);}else{if(!s.matches("[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?"))throw new NumberFormatException();n=Double.parseDouble(s);}}fallback=!Double.isFinite(n);}catch(NumberFormatException e){fallback=true;}if(fallback)n=0;need(n>=0,"可用资金不能小于0");n=Math.floor(n*100+0.5)/100;need(Double.isFinite(n),"金额超出可保存范围");candidate.put("cashBalance",n);}return new JSONObject().put("expected",new JSONObject(expected.toString())).put("candidate",candidate).put("changed",!equal(expected,candidate)).put("cashEdited",d.getBoolean("editCash")).put("warning",fallback?"非有限或无效输入按旧规则转换为0元；请核对后再保存":"").put("cashMeaning","手工现金余额快照；不是出入金流水，不生成交易");}
}
